export interface ImageState {
  originalUrl: string;
  width: number;
  height: number;
  aspectRatio: number;
  fileName: string;
}

export interface SliceResult {
  id: string;
  url: string;
  index: number;
  format: string;
}

export type ExportFormat = 'jpeg' | 'png' | 'gif';

export interface ProcessingOptions {
  targetWidth: number;
  targetHeight: number;
  sliceHeight: number;
  keepAspectRatio: boolean;
  exportFormat: ExportFormat;
}

import { SliceResult, ProcessingOptions } from '../types';

export const processImage = async (
  imageElement: HTMLImageElement,
  options: ProcessingOptions
): Promise<SliceResult[]> => {
  const { targetWidth, targetHeight, sliceHeight, exportFormat } = options;

  // 1. Resize the image to the target dimensions
  const resizeCanvas = document.createElement('canvas');
  resizeCanvas.width = targetWidth;
  resizeCanvas.height = targetHeight;
  const ctx = resizeCanvas.getContext('2d');

  if (!ctx) throw new Error('Could not get canvas context');

  // For JPEG, we want a white background instead of transparent
  if (exportFormat === 'jpeg') {
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, targetWidth, targetHeight);
  }

  ctx.drawImage(imageElement, 0, 0, targetWidth, targetHeight);

  // 2. Slice the resized image
  const slices: SliceResult[] = [];
  let currentY = 0;
  let index = 0;

  const mimeType = `image/${exportFormat}`;

  while (currentY < targetHeight) {
    const actualSliceHeight = Math.min(sliceHeight, targetHeight - currentY);

    const sliceCanvas = document.createElement('canvas');
    sliceCanvas.width = targetWidth;
    sliceCanvas.height = actualSliceHeight;
    const sliceCtx = sliceCanvas.getContext('2d');

    if (sliceCtx) {
      // Background for slices if JPEG
      if (exportFormat === 'jpeg') {
        sliceCtx.fillStyle = '#FFFFFF';
        sliceCtx.fillRect(0, 0, targetWidth, actualSliceHeight);
      }

      sliceCtx.drawImage(
        resizeCanvas,
        0, currentY, targetWidth, actualSliceHeight, // Source
        0, 0, targetWidth, actualSliceHeight        // Destination
      );

      slices.push({
        id: `slice-${Date.now()}-${index}`,
        url: sliceCanvas.toDataURL(mimeType, exportFormat === 'jpeg' ? 0.92 : undefined),
        index,
        format: exportFormat
      });
    }

    currentY += actualSliceHeight;
    index++;
  }

  return slices;
};

export const loadImage = (url: string): Promise<HTMLImageElement> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = url;
  });
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { ImageState, SliceResult, ProcessingOptions, ExportFormat } from './types';
import { processImage, loadImage } from './services/imageService';
import { analyzeImageSlicing } from './services/aiService';
import NumberInput from './components/NumberInput';

const App: React.FC = () => {
  const [image, setImage] = useState<ImageState | null>(null);
  const [slices, setSlices] = useState<SliceResult[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
