                                </a>
                              </div>
                            </div>
                          ))}
                          {img.slices.length > 5 && (
                            <div className="w-16 h-16 shrink-0 rounded-lg bg-slate-50 border border-slate-100 flex items-center justify-center text-[10px] font-bold text-slate-400">
                              +{img.slices.length - 5}
                            </div>
                          )}
