            </div>
          ) : (
            <div className="space-y-8 animate-fade-in">
              {options.mode === 'mosaic' && !images.some(img => img.status === 'completed') && (
                <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl flex items-center gap-3">
                  <div className="bg-blue-500 text-white p-2 rounded-lg">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                  </div>
                  <div className="flex-1">
                    <h4 className="text-sm font-bold text-blue-900">高清拼图预览</h4>
                    <p className="text-xs text-blue-700">当前宽度: <span className="font-bold">{options.targetWidth}px</span>。拖动可排版，导出时将应用最高平滑算法。</p>
                  </div>
                </div>
              )}

              <div className={`grid gap-6 ${options.mode === 'mosaic' && !images.some(i => i.status === 'completed') ? 'grid-cols-1' : 'grid-cols-1 xl:grid-cols-2'}`}>
                {images.map((img, idx) => (
                  <div 
                    key={img.id} 
                    draggable={canReorder}
                    onDragStart={() => onDragStart(idx)}
                    onDragOver={(e) => onDragOver(e, idx)}
                    onDragEnd={onDragEnd}
                    className={`bg-white rounded-2xl border border-slate-100 overflow-hidden shadow-sm flex flex-col group relative transition-all duration-200 
                      ${canReorder ? 'cursor-grab active:cursor-grabbing hover:border-blue-300 hover:shadow-md' : ''} 
                      ${draggedIndex === idx ? 'opacity-40 scale-95 border-blue-500' : ''}`}
                  >
                    {options.mode === 'mosaic' && !images.some(i => i.status === 'completed') && (
                      <div className="absolute left-4 top-4 z-10 flex items-center gap-2">
                        <div className="w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold shadow-lg">
                          {idx + 1}
                        </div>
                        <div className="bg-white/90 p-1.5 rounded-lg shadow-sm border border-slate-100 opacity-0 group-hover:opacity-100 transition-opacity">
                          <svg className="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
                          </svg>
                        </div>
                      </div>
                    )}

                    <div className="relative aspect-video bg-slate-50 flex items-center justify-center overflow-hidden pointer-events-none">
                      <img src={img.originalUrl} alt={img.fileName} className="w-full h-full object-contain" />
                      <div className="absolute top-2 right-2 flex gap-2 pointer-events-auto">
                        {img.status === 'completed' && (
                          <span className="bg-green-500 text-white text-[10px] font-bold px-2 py-1 rounded-md shadow-sm">已处理</span>
                        )}
                        {img.status === 'processing' && (
                          <span className="bg-blue-500 text-white text-[10px] font-bold px-2 py-1 rounded-md shadow-sm animate-pulse">高清渲染中</span>
                        )}
                        <button 
                          onClick={() => removeImage(img.id)}
                          className="bg-white/90 hover:bg-white text-slate-400 hover:text-red-500 p-1.5 rounded-lg shadow-sm transition-colors"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                      </div>
                    </div>

                    <div className="p-4 flex flex-col gap-3">
                      <div className="flex justify-between items-start">
                        <div className="min-w-0">
                          <h4 className="font-bold text-slate-800 truncate text-sm" title={img.fileName}>{img.fileName}</h4>
                          <p className="text-[10px] text-slate-400">原始: {img.width}x{img.height} • {options.targetWidth}px 宽渲染</p>
                        </div>
                        {img.slices.length > 0 && (
                          <div className="text-right">
                             <p className="text-[10px] font-bold text-blue-600">{img.slices.length} {options.enableSlicing ? '高清切片' : '完整结果'}</p>
                          </div>
                        )}
                      </div>

                      {img.slices.length > 0 && (
                        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-slate-200">
                          {img.slices.map((slice, i) => (
                            <div 
                              key={slice.id} 
                              className={`w-16 h-16 shrink-0 rounded-lg border border-slate-100 overflow-hidden relative group/slice cursor-pointer transition-all ${optimizingIds.has(`${img.id}-${i}`) ? 'animate-pulse scale-90 border-purple-400' : ''}`}
                              onClick={(e) => { e.stopPropagation(); setPreviewData({ imageId: img.id, sliceIndex: i }); }}
                            >
                              <img src={slice.url} className="w-full h-full object-cover" />
                              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/slice:opacity-100 flex items-center justify-center transition-opacity gap-1">
                                <button className="text-white p-1 hover:scale-110 transition-transform">
                                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                                </button>
                              </div>
                              {optimizingIds.has(`${img.id}-${i}`) && (
                                <div className="absolute inset-0 bg-purple-500/20 flex items-center justify-center">
                                  <svg className="animate-spin h-4 w-4 text-purple-600" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                                </div>
                              )}
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>

      {currentPreviewSlice && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/90 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setPreviewData(null)}>
          <div className="relative w-full max-w-5xl bg-white rounded-3xl overflow-hidden shadow-2xl flex flex-col md:flex-row h-[85vh]" onClick={e => e.stopPropagation()}>
            <div className="flex-1 bg-slate-100 relative overflow-hidden flex items-center justify-center p-4">
              <img src={currentPreviewSlice.slice.url} alt="Preview" className="max-w-full max-h-full object-contain shadow-lg rounded-lg" />

              <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 flex justify-between px-4 pointer-events-none">
                <button 
                  onClick={() => navigatePreview(-1)} 
                  className="w-12 h-12 rounded-full bg-white/80 hover:bg-white shadow-lg flex items-center justify-center pointer-events-auto transition-transform hover:scale-110 active:scale-95 disabled:opacity-30 disabled:pointer-events-none"
                  disabled={currentPreviewSlice.total <= 1}
                >
                  <svg className="w-6 h-6 text-slate-800" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
                </button>
                <button 
                  onClick={() => navigatePreview(1)} 
                  className="w-12 h-12 rounded-full bg-white/80 hover:bg-white shadow-lg flex items-center justify-center pointer-events-auto transition-transform hover:scale-110 active:scale-95 disabled:opacity-30 disabled:pointer-events-none"
                  disabled={currentPreviewSlice.total <= 1}
                >
                  <svg className="w-6 h-6 text-slate-800" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" /></svg>
                </button>
              </div>
            </div>

            <div className="w-full md:w-80 p-8 flex flex-col bg-white border-l border-slate-100">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <h3 className="text-xl font-bold text-slate-800 truncate" title={currentPreviewSlice.fileName}>{currentPreviewSlice.fileName}</h3>
                  <p className="text-sm text-slate-400 mt-1">
                    {options.enableSlicing ? `切片 ${currentPreviewSlice.index + 1} / ${currentPreviewSlice.total}` : '高清预览'}
                  </p>
                </div>
                <button onClick={() => setPreviewData(null)} className="text-slate-400 hover:text-slate-600 transition-colors p-1">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>

              <div className="space-y-6 flex-1">
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">详情</p>
                  <div className="space-y-3">
                    <div className="flex justify-between items-center">
                      <span className="text-sm text-slate-500">渲染大小</span>
                      <span className="text-sm font-bold text-blue-600">{currentPreviewSlice.slice.sizeLabel}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-sm text-slate-500">导出格式</span>
                      <span className="text-sm font-bold text-slate-700 uppercase">{currentPreviewSlice.slice.format} (Q:1.0)</span>
                    </div>
                  </div>
                </div>

                <div className="flex flex-col gap-3">
                  <button 
                    onClick={() => handleAiOptimizeSlice(currentPreviewSlice.imageId, currentPreviewSlice.index)}
                    disabled={optimizingIds.has(`${currentPreviewSlice.imageId}-${currentPreviewSlice.index}`)}
                    className="w-full bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white py-3.5 rounded-xl font-bold transition-all shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed group relative overflow-hidden"
                  >
                    {optimizingIds.has(`${currentPreviewSlice.imageId}-${currentPreviewSlice.index}`) ? (
                      <>
                        <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                        AI 深度增强中...
                      </>
                    ) : (
                      <>
                        <span className="group-hover:animate-pulse">✨</span>
                        AI 高清像素修复
                      </>
                    )}
                  </button>
                  <a 
                    href={currentPreviewSlice.slice.url} 
                    download={`${currentPreviewSlice.fileName}${options.enableSlicing ? `_slice_${currentPreviewSlice.index + 1}` : ''}.${currentPreviewSlice.slice.format}`}
                    className="w-full bg-slate-900 hover:bg-black text-white py-3.5 rounded-xl font-bold transition-all shadow-lg flex items-center justify-center gap-2"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                    下载高清结果
                  </a>
                </div>
              </div>

              <div className="mt-8 pt-6 border-t border-slate-50 text-center">
                <p className="text-[10px] text-slate-300 font-bold uppercase tracking-widest">Powered by Gemini 3 Pro</p>
                <p className="text-[10px] text-slate-300 font-bold uppercase tracking-widest mt-1">Design by JJBoo</p>
              </div>
            </div>
          </div>
        </div>
      )}

      <footer className="w-full max-w-7xl mt-12 py-8 border-t border-slate-100 text-center text-slate-400 text-sm">
        <p>&copy; 2024 JJBoo PixelSlice. Design by JJBoo</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef, useMemo } from 'react';
import { ImageState, SliceResult, ProcessingOptions, ExportFormat, ProcessingMode } from './types';
import { processImage, loadImage, loadAllImages, stitchImages } from './services/imageService';
import { analyzeImageSlicing, enhanceImageQuality } from './services/aiService';
import NumberInput from './components/NumberInput';

// Window extension for AI Studio key management
// Fix: Define AIStudio interface to match the environment's expected type and modifiers
interface AIStudio {
  hasSelectedApiKey: () => Promise<boolean>;
  openSelectKey: () => Promise<void>;
}

declare global {
  interface Window {
    aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  const [images, setImages] = useState<ImageState[]>([]);
  const [isBatchProcessing, setIsBatchProcessing] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [optimizingIds, setOptimizingIds] = useState<Set<string>>(new Set());
  const [previewData, setPreviewData] = useState<{ imageId: string; sliceIndex: number } | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  const [options, setOptions] = useState<ProcessingOptions>({
    mode: 'individual',
    targetWidth: 0,
    targetHeight: 0,
    sliceHeight: 1200,
    enableSlicing: true,
    keepAspectRatio: true,
    exportFormat: 'jpeg',
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files || []) as File[];
    if (files.length === 0) return;

    files.forEach(file => {
      const url = URL.createObjectURL(file);
      const img = new Image();
      img.onload = () => {
        const newImage: ImageState = {
          id: Math.random().toString(36).substr(2, 9),
          originalUrl: url,
          width: img.width,
          height: img.height,
          aspectRatio: img.width / img.height,
          fileName: file.name.split('.').slice(0, -1).join('.'),
          status: 'pending',
          slices: []
        };

        setImages(prev => [...prev, newImage]);

        if (images.length === 0 && options.targetWidth === 0) {
          setOptions(prev => ({
            ...prev,
            targetWidth: img.width,
            targetHeight: img.height
          }));
        }
      };
      img.src = url;
    });
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => prev.filter(img => img.id !== id));
    if (previewData?.imageId === id) setPreviewData(null);
  };

  const clearAll = () => {
    setImages([]);
    setPreviewData(null);
  };

  const useMaxOriginalWidth = () => {
    if (images.length === 0) return;
    const maxWidth = Math.max(...images.map(img => img.width));
    updateWidth(maxWidth);
  };

  const updateWidth = (newWidth: number) => {
    if (options.keepAspectRatio && images.length > 0) {
      const firstImg = images[0];
      const newHeight = Math.round(newWidth / firstImg.aspectRatio);
      setOptions(prev => ({ ...prev, targetWidth: newWidth, targetHeight: newHeight }));
    } else {
      setOptions(prev => ({ ...prev, targetWidth: newWidth }));
    }
  };

  const updateHeight = (newHeight: number) => {
    if (options.keepAspectRatio && images.length > 0) {
      const firstImg = images[0];
      const newWidth = Math.round(newHeight * firstImg.aspectRatio);
      setOptions(prev => ({ ...prev, targetHeight: newHeight, targetWidth: newWidth }));
    } else {
      setOptions(prev => ({ ...prev, targetHeight: newHeight }));
    }
  };

  const onDragStart = (index: number) => {
    if (isBatchProcessing || images.some(img => img.status === 'completed')) return;
    setDraggedIndex(index);
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;

    const newImages = [...images];
    const item = newImages.splice(draggedIndex, 1)[0];
    newImages.splice(index, 0, item);
    setImages(newImages);
    setDraggedIndex(index);
  };

  const onDragEnd = () => {
    setDraggedIndex(null);
  };

  const handleStartProcessing = async () => {
    if (images.length === 0) return;
    setIsBatchProcessing(true);

    if (options.mode === 'mosaic') {
      try {
        const loadedImages = await loadAllImages(images.map(img => img.originalUrl));
        const stitchedCanvas = await stitchImages(loadedImages, options.targetWidth, options.exportFormat);

        const mosaicOptions = { 
          ...options, 
          targetHeight: stitchedCanvas.height 
        };
        const results = await processImage(stitchedCanvas, mosaicOptions);

        const mosaicResult: ImageState = {
          id: 'mosaic-result-' + Date.now(),
          originalUrl: stitchedCanvas.toDataURL(`image/${options.exportFormat}`, 1.0),
          width: stitchedCanvas.width,
          height: stitchedCanvas.height,
          aspectRatio: stitchedCanvas.width / stitchedCanvas.height,
          fileName: 'stitched_mosaic',
          status: 'completed',
          slices: results
        };

        setImages([mosaicResult]);
      } catch (err) {
        console.error(err);
      }
    } else {
      const processSingle = async (imgState: ImageState) => {
        setImages(prev => prev.map(img => img.id === imgState.id ? { ...img, status: 'processing' } : img));
        try {
          const imgElement = await loadImage(imgState.originalUrl);
          const currentOptions = { ...options };
          if (options.keepAspectRatio) {
            currentOptions.targetHeight = Math.round(options.targetWidth / imgState.aspectRatio);
          }

          const results = await processImage(imgElement, currentOptions);
          setImages(prev => prev.map(img => img.id === imgState.id ? { 
            ...img, 
            status: 'completed', 
            slices: results 
          } : img));
        } catch (err) {
          console.error(err);
          setImages(prev => prev.map(img => img.id === imgState.id ? { ...img, status: 'error' } : img));
        }
      };

      await Promise.all(images.map(img => processSingle(img)));
    }
    setIsBatchProcessing(false);
  };

  const handleAiOptimizeSlice = async (imageId: string, sliceIndex: number) => {
    const hasKey = await window.aistudio.hasSelectedApiKey();
    if (!hasKey) {
      await window.aistudio.openSelectKey();
      // Proceed after triggering (assuming user selects correctly or uses current)
    }

    const sliceId = `${imageId}-${sliceIndex}`;
    setOptimizingIds(prev => new Set(prev).add(sliceId));

    try {
      const img = images.find(i => i.id === imageId);
      if (!img || !img.slices[sliceIndex]) return;

      const enhancedUrl = await enhanceImageQuality(img.slices[sliceIndex].url);

      setImages(prev => prev.map(i => {
        if (i.id === imageId) {
          const newSlices = [...i.slices];
          newSlices[sliceIndex] = { ...newSlices[sliceIndex], url: enhancedUrl };
          return { ...i, slices: newSlices };
        }
        return i;
      }));
    } catch (err: any) {
      if (err.message === 'KEY_REQUIRED') {
        await window.aistudio.openSelectKey();
      } else {
        alert('AI 优化失败，请检查网络或重试');
      }
    } finally {
      setOptimizingIds(prev => {
        const next = new Set(prev);
        next.delete(sliceId);
        return next;
      });
    }
  };

  const handleAiAnalyze = async () => {
    if (images.length === 0) return;
    setIsAnalyzing(true);
    try {
      const blobResponse = await fetch(images[0].originalUrl);
      const blob = await blobResponse.blob();
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(blob);
      });

      const result = await analyzeImageSlicing(base64);
      if (result && result.suggestedHeight) {
        setOptions(prev => ({ ...prev, sliceHeight: result.suggestedHeight }));
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadAll = () => {
    images.forEach(img => {
      img.slices.forEach((slice, idx) => {
        const link = document.createElement('a');
        link.href = slice.url;
        link.download = `${img.fileName}${options.enableSlicing ? `_slice_${idx + 1}` : ''}.${slice.format}`;
        link.click();
      });
    });
  };

  const combinedMetrics = useMemo(() => {
    if (images.length === 0) return { height: 0, slices: 0 };
    let totalHeight = 0;
    if (options.mode === 'mosaic') {
      images.forEach(img => {
        const scale = options.targetWidth / img.width;
        totalHeight += img.height * scale;
      });
    } else {
       const firstImg = images[0];
       totalHeight = options.keepAspectRatio ? (options.targetWidth / firstImg.aspectRatio) : options.targetHeight;
    }
    const slices = options.enableSlicing ? Math.ceil(totalHeight / options.sliceHeight) : 1;
    return { height: Math.round(totalHeight), slices: options.mode === 'mosaic' ? slices : (options.enableSlicing ? totalSlices : images.length) };
  }, [images, options]);

  const totalSlices = useMemo(() => {
    if (options.mode === 'mosaic') {
      if (images.length === 0) return 0;
      let combinedHeight = 0;
      images.forEach(img => {
        const scale = options.targetWidth / img.width;
        combinedHeight += img.height * scale;
      });
      return options.enableSlicing ? Math.ceil(combinedHeight / options.sliceHeight) : 1;
    }
    if (!options.enableSlicing) return images.length;
    return images.reduce((acc, img) => acc + Math.ceil((options.keepAspectRatio ? (options.targetWidth / img.aspectRatio) : options.targetHeight) / options.sliceHeight), 0);
  }, [images, options]);

  const currentPreviewSlice = useMemo(() => {
    if (!previewData) return null;
    const img = images.find(i => i.id === previewData.imageId);
    if (!img) return null;
    return {
      slice: img.slices[previewData.sliceIndex],
      fileName: img.fileName,
      total: img.slices.length,
      index: previewData.sliceIndex,
      imageId: img.id
    };
  }, [previewData, images]);

  const navigatePreview = (direction: number) => {
    if (!previewData) return;
    const img = images.find(i => i.id === previewData.imageId);
    if (!img) return;
    const nextIndex = (previewData.sliceIndex + direction + img.slices.length) % img.slices.length;
    setPreviewData({ ...previewData, sliceIndex: nextIndex });
  };

  const canReorder = options.mode === 'mosaic' && !isBatchProcessing && !images.some(img => img.status === 'completed');

  return (
    <div className="min-h-screen flex flex-col items-center p-4 md:p-8">
      <header className="w-full max-w-7xl mb-8 flex justify-between items-center">
        <div>
